## Requirements

Use **ML.NET** (`Microsoft.ML`) for multiclass text classification. This is structured/tabular data — do NOT use an LLM.

### Guardrails from the skill:
1. Set `MLContext(seed: 42)` for reproducibility
2. Use `TrainTestSplit` — never evaluate on training data
3. Log evaluation metrics (macro accuracy, log-loss per class)
4. Use `PredictionEnginePool` in ASP.NET Core (not singleton PredictionEngine — it's not thread-safe)
5. Register all services via DI

### Files to create/modify:

1. **Edit `TicketClassifier.csproj`** — add:
   ```xml
   <PackageReference Include="Microsoft.ML" Version="4.*" />
   <PackageReference Include="Microsoft.Extensions.ML" Version="4.*" />
   ```

2. **Create `Models/TicketData.cs`** — ML.NET input model:
   ```csharp
   using Microsoft.ML.Data;

   namespace TicketClassifier.Models;

   public class TicketData
   {
       [LoadColumn(0)]
       public string Subject { get; set; } = string.Empty;

       [LoadColumn(1)]
       public string Description { get; set; } = string.Empty;

       [LoadColumn(2)]
       public float Priority { get; set; }

       [LoadColumn(3)]
       public string Category { get; set; } = string.Empty;
   }
   ```

3. **Create `Models/TicketPrediction.cs`** — ML.NET output model:
   ```csharp
   using Microsoft.ML.Data;

   namespace TicketClassifier.Models;

   public class TicketPrediction
   {
       [ColumnName("PredictedLabel")]
       public string PredictedCategory { get; set; } = string.Empty;

       public float[] Score { get; set; } = [];
   }
   ```

4. **Create `Models/TicketRequest.cs`** — API request DTO:
   ```csharp
   namespace TicketClassifier.Models;

   public class TicketRequest
   {
       public string Subject { get; set; } = string.Empty;
       public string Description { get; set; } = string.Empty;
       public int Priority { get; set; }
   }
   ```

5. **Create `Models/TicketClassificationResult.cs`** — API response DTO:
   ```csharp
   namespace TicketClassifier.Models;

   public class TicketClassificationResult
   {
       public string PredictedCategory { get; set; } = string.Empty;
       public Dictionary<string, float> Confidence { get; set; } = new();
   }
   ```

6. **Create `Services/ModelTrainerService.cs`** — A hosted service that trains the model at startup, logs evaluation metrics, and saves the model to disk:
   ```csharp
   using Microsoft.ML;
   using TicketClassifier.Models;

   namespace TicketClassifier.Services;

   public class ModelTrainerService : IHostedService
   {
       private readonly ILogger<ModelTrainerService> _logger;
       private readonly IWebHostEnvironment _env;

       public static string ModelPath => Path.Combine(AppContext.BaseDirectory, "ticket_model.zip");

       public ModelTrainerService(ILogger<ModelTrainerService> logger, IWebHostEnvironment env)
       {
           _logger = logger;
           _env = env;
       }

       public Task StartAsync(CancellationToken cancellationToken)
       {
           var mlContext = new MLContext(seed: 42);

           var dataPath = Path.Combine(_env.ContentRootPath, "Data", "tickets.csv");
           IDataView data = mlContext.Data.LoadFromTextFile<TicketData>(
               dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

           var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

           // Featurize text columns and combine with Priority
           var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
               .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
               .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
               .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
               .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
               .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

           _logger.LogInformation("Training ticket classification model...");
           var model = pipeline.Fit(split.TrainSet);

           // Evaluate on test set
           var predictions = model.Transform(split.TestSet);
           var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

           _logger.LogInformation("Model evaluation metrics:");
           _logger.LogInformation("  Macro Accuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
           _logger.LogInformation("  Micro Accuracy:    {MicroAccuracy:F4}", metrics.MicroAccuracy);
           _logger.LogInformation("  Log Loss:          {LogLoss:F4}", metrics.LogLoss);
           _logger.LogInformation("  Log Loss Reduction:{LogLossReduction:F4}", metrics.LogLossReduction);

           foreach (var classMetric in metrics.PerClassLogLoss.Select((value, index) => (value, index)))
           {
               _logger.LogInformation("  Class {Index} Log Loss: {LogLoss:F4}", classMetric.index, classMetric.value);
           }

           mlContext.Model.Save(model, data.Schema, ModelPath);
           _logger.LogInformation("Model saved to {Path}", ModelPath);

           return Task.CompletedTask;
       }

       public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
   }
   ```

7. **Create `Controllers/TicketClassifierController.cs`**:
   ```csharp
   using Microsoft.AspNetCore.Mvc;
   using Microsoft.Extensions.ML;
   using TicketClassifier.Models;

   namespace TicketClassifier.Controllers;

   [ApiController]
   [Route("api/[controller]")]
   public class TicketClassifierController : ControllerBase
   {
       private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;

       public TicketClassifierController(PredictionEnginePool<TicketData, TicketPrediction> predictionEnginePool)
       {
           _predictionEnginePool = predictionEnginePool;
       }

       [HttpPost("classify")]
       public ActionResult<TicketClassificationResult> Classify([FromBody] TicketRequest request)
       {
           var input = new TicketData
           {
               Subject = request.Subject,
               Description = request.Description,
               Priority = request.Priority
           };

           var prediction = _predictionEnginePool.Predict(input);

           string[] categories = ["Billing", "General", "Technical"];
           var confidence = new Dictionary<string, float>();
           for (int i = 0; i < categories.Length && i < prediction.Score.Length; i++)
           {
               confidence[categories[i]] = prediction.Score[i];
           }

           return Ok(new TicketClassificationResult
           {
               PredictedCategory = prediction.PredictedCategory,
               Confidence = confidence
           });
       }
   }
   ```

8. **Edit `Program.cs`** — Register the model trainer hosted service and prediction engine pool:
   ```csharp
   using Microsoft.Extensions.ML;
   using TicketClassifier.Models;
   using TicketClassifier.Services;

   var builder = WebApplication.CreateBuilder(args);
   builder.Services.AddControllers();
   builder.Services.AddHostedService<ModelTrainerService>();
   builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
       .FromFile(ModelTrainerService.ModelPath);

   var app = builder.Build();
   app.MapControllers();
   app.Run();
   ```

## Important implementation notes:
- The confidence dictionary categories should actually be derived from the model's label mapping at runtime rather than hardcoded. However, for this small training set with known categories, use the sorted known categories: Billing, General, Technical (alphabetical order, which matches ML.NET's MapValueToKey default behavior).
- Make sure `Priority` is `float` in TicketData since ML.NET works with float features.
- Use `allowQuoting: true` in LoadFromTextFile since the CSV has quoted fields.

After creating all files, run `dotnet restore` and `dotnet build` to verify everything compiles. If there are errors, fix them.

